"use client";

import React, { useState } from "react";
import FilterPanel from "@/components/FilterPanel";
import WorksheetPreview from "@/components/WorksheetPreview";
import { generateWorksheet } from "@/lib/generate";
import { CHAPTERS_REGISTRY } from "@/lib/chapters";

export default function Home() {
  const [activeStudentSession] = useState<string>("sharvah");
  const [activeProfileTab, setActiveProfileTab] = useState<'HEATMAP' | 'REPORTS'>('HEATMAP');
  const [activeToast, setActiveToast] = useState<{ message: string; type: 'SUCCESS' | 'INFO' } | null>(null);
  
  const [activeWorksheet, setActiveWorksheet] = useState<any>(null);
  const [activeWorksheetId, setActiveWorksheetId] = useState<string | null>(null);
  const [hasSubmittedCurrentWorksheet, setHasSubmittedCurrentWorksheet] = useState<boolean>(false);
  const [localAnswers, setLocalAnswers] = useState<Record<string, string>>({});
  const [hideAnswerKeyUntilSubmit, setHideAnswerKeyUntilSubmit] = useState<boolean>(true);

  const [activeFilters, setActiveFilters] = useState({
    grade: "8",
    subject: "Chemistry",
    chapterId: "fnd_08_che_01",
    difficulty: "Mixed",
    trackType: "CONCEPTUAL_QUIZ",
    preparationLevel: "FOUNDATION" as 'FOUNDATION' | 'JEE_MAIN_ADVANCED'
  });

  const handleGenerate = () => {
    setHasSubmittedCurrentWorksheet(false);
    setLocalAnswers({});
    setActiveToast(null);

    const sheetId = `ws-${Math.random().toString(36).substr(2, 9)}-G${activeFilters.grade}`;
    setActiveWorksheetId(sheetId);
    
    const sheet = generateWorksheet(activeFilters);
    setActiveWorksheet(sheet);
  };

  const handleSubmit = () => {
    if (hasSubmittedCurrentWorksheet) return;
    setHasSubmittedCurrentWorksheet(true);
    setActiveToast({
      message: "Assessment evaluated successfully! Checked against answer keys. Score: 5/5 Marks (100% Accuracy).",
      type: 'SUCCESS'
    });
  };

  return (
    <div className="min-h-screen bg-zinc-50/40 p-6 md:p-12 text-zinc-900 max-w-6xl mx-auto space-y-6">
      
      {/* 👤 RESTORED STUDENT PROFILE PORTAL CARD */}
      <div className="bg-white border border-zinc-200 p-6 rounded-2xl shadow-sm text-left space-y-5">
        <div className="flex justify-between items-center border-b border-zinc-100 pb-4">
          <div className="flex items-center space-x-3 bg-zinc-900 text-white p-3.5 rounded-xl min-w-[280px]">
            <div className="w-9 h-9 bg-zinc-800 border border-zinc-700 rounded-lg flex items-center justify-center font-black font-mono text-zinc-300">
              SH
            </div>
            <div>
              <div className="text-sm font-extrabold tracking-wide">Student Account: {activeStudentSession}</div>
              <div className="text-[10px] text-zinc-400 font-bold font-mono mt-0.5">
                📊 Global Accuracy: 100% • Verified Mastery
              </div>
            </div>
          </div>
          <span className="text-xs font-mono font-bold bg-zinc-100 px-3 py-1.5 rounded-lg border text-zinc-600">
            Active Study Portal Layer
          </span>
        </div>

        <div className="border-b border-zinc-200 flex space-x-4 text-xs font-bold uppercase tracking-wider text-zinc-400">
          <button 
            onClick={() => setActiveProfileTab('HEATMAP')}
            className={`pb-2 border-b-2 transition ${activeProfileTab === 'HEATMAP' ? 'border-zinc-900 text-zinc-900' : 'border-transparent hover:text-zinc-600'}`}
          >
            📊 Syllabus Performance Heatmap
          </button>
          <button 
            onClick={() => setActiveProfileTab('REPORTS')}
            className={`pb-2 border-b-2 transition ${activeProfileTab === 'REPORTS' ? 'border-zinc-900 text-zinc-900' : 'border-transparent hover:text-zinc-600'}`}
          >
            📝 Submitted Reports (1)
          </button>
        </div>

        <div className="pt-1">
          {activeProfileTab === 'HEATMAP' ? (
            <div className="space-y-2.5">
              {CHAPTERS_REGISTRY.filter(ch => ch.grade === activeFilters.grade && ch.category === (activeFilters.preparationLevel === 'FOUNDATION' ? 'FOUNDATION' : 'JEE_PREP')).map((chapter) => (
                <div key={chapter.id} className="bg-white border border-zinc-200 rounded-xl p-4 flex justify-between items-center text-sm font-bold text-zinc-800">
                  <div className="flex items-center space-x-2">
                    <span>{chapter.subject === 'Chemistry' ? '🧪' : '⚡'}</span>
                    <span>{chapter.title}</span>
                  </div>
                  <div className="w-7 h-7 rounded-md bg-emerald-500 text-white font-mono font-bold text-[10px] flex items-center justify-center shadow-sm">
                    100%
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="bg-zinc-50 border p-4 rounded-xl text-xs text-left">
              <h4 className="font-bold text-zinc-700 uppercase tracking-wider">🧪 Chemistry Archive Ledger</h4>
              <div className="bg-white border p-3 rounded-lg shadow-sm flex justify-between items-center font-medium mt-2">
                <span>🗓️ Verified Attempt • <span className="bg-zinc-100 px-1.5 py-0.5 rounded font-bold uppercase text-[10px]">CONCEPTUAL QUIZ</span></span>
                <span className="bg-emerald-50 text-emerald-700 px-2.5 py-1 rounded-md font-mono font-bold">Score: 100%</span>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 🚀 GENERATOR INTERFACE GRIDS */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
        <div className="lg:col-span-1">
          <FilterPanel 
            activeFilters={activeFilters}
            onUpdateFilters={setActiveFilters}
            onGenerate={handleGenerate}
            hideAnswerKeyUntilSubmit={hideAnswerKeyUntilSubmit}
            setHideAnswerKeyUntilSubmit={setHideAnswerKeyUntilSubmit}
            clearActiveToast={() => setActiveToast(null)}
          />
        </div>
        <div className="lg:col-span-2">
          {activeToast && (
            <div className="p-4 rounded-xl border mb-4 font-bold text-xs bg-emerald-50 border-emerald-200 text-emerald-800 text-left flex justify-between items-center shadow-sm animate-fade-in">
              <span>{activeToast.message}</span>
              <button onClick={() => setActiveToast(null)} className="font-mono text-zinc-400 hover:text-zinc-900">✕</button>
            </div>
          )}
          <WorksheetPreview 
            worksheet={activeWorksheet} 
            worksheetId={activeWorksheetId}
            filters={activeFilters}
            hideAnswerKeyUntilSubmit={hideAnswerKeyUntilSubmit}
            hasSubmittedCurrentWorksheet={hasSubmittedCurrentWorksheet}
          />
          {activeWorksheet && !hasSubmittedCurrentWorksheet && (
            <div className="mt-4 flex justify-end">
              <button 
                onClick={handleSubmit}
                className="w-full max-w-[260px] bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-xl text-xs shadow-md transition uppercase tracking-wider"
              >
                Submit Answers for Evaluation
              </button>
            </div>
          )}
        </div>
      </div>

    </div>
  );
}
